    public virtual void handleTicker(WebSocketClient client, object message)
    {
        //
        //     {
        //         "tokenId": "19120407572139442221452465677574895365338028945317996490376653704877573103648",
        //         "outcomeSide": 1,
        //         "price": "0.85",
