    public virtual void handleTrades(WebSocketClient client, object message)
    {
        //
        //     {
        //         "tokenId": "19120407572139442221452465677574895365338028945317996490376653704877573103648",
        //         "side": "Buy",
        //         "outcomeSide": 1,
        //         "price": "0.85",
        //         "shares": "10",
        //         "amount": "8.5",
        //         "marketId": 2764,
        //         "msgType": "market.last.trade"
        //     }
        //
        object tokenId = this.safeString(message, "tokenId");
        object outcomeObj = this.safeDict(this.outcomes_by_id, tokenId);
        object sym = this.safeString(outcomeObj, "outcome");
        if (isTrue(isEqual(sym, null)))
        {
            return;
        }
        object now = this.milliseconds();
        object trade = this.safePredictionTrade(new Dictionary<string, object>() {
            { "id", null },
            { "info", message },
            { "timestamp", now },
            { "datetime", this.iso8601(now) },
            { "outcome", sym },
            { "outcomeId", tokenId },
            { "label", this.safeString(outcomeObj, "label") },
            { "market", this.safeString(outcomeObj, "market") },
            { "order", null },
            { "type", null },
            { "side", this.safeStringLower(message, "side") },
            { "takerOrMaker", "taker" },
            { "price", this.safeNumber(message, "price") },
            { "amount", this.safeNumber(message, "shares") },
            { "cost", this.safeNumber(message, "amount") },
            { "fee", null },
        }, outcomeObj);
        if (isTrue(isEqual(this.trades, null)))
        {
            this.trades = this.createSafeDictionary();
        }
        if (isTrue(isEqual(this.safeValue(this.trades, sym), null)))
        {
            object tradesLimit = this.safeInteger(this.options, "tradesLimit", 1000);
            ((IDictionary<string,object>)this.trades)[(string)sym] = new ArrayCache(tradesLimit);
        }
        object stored = getValue(this.trades, sym);
        callDynamically(stored, "append", new object[] {trade});
        callDynamically(client as WebSocketClient, "resolve", new object[] {stored, add("trades::", sym)});
    }

    /**
     * @method
     * @name opinion#watchOrders
     * @description streams the authenticated user's order updates of one market - the venue channel is per-market, so the outcome argument is required
     * @see https://docs.opinion.trade/developer-guide/opinion-websocket/user-channels
